CREATE OR REPLACE FUNCTION analysis_private.get_analysis_module(p_module_type text, p_entity_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_row analysis_private.analysis_sync_modules;
begin
  if v_owner is null then raise exception 'ANALYSIS_AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_row from analysis_private.analysis_sync_modules
    where user_id=v_owner and module_type=p_module_type and entity_key=p_entity_key;
  if not found then return null; end if;
  return analysis_private.module_json(v_row);
end $function$

CREATE OR REPLACE FUNCTION analysis_private.list_analysis_modules()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_rows jsonb;
begin
  if v_owner is null then raise exception 'ANALYSIS_AUTH_REQUIRED' using errcode='42501'; end if;
  select coalesce(jsonb_agg(analysis_private.module_json(row_value) order by row_value.published_at desc),'[]'::jsonb)
    into v_rows from analysis_private.analysis_sync_modules row_value where row_value.user_id=v_owner;
  return v_rows;
end $function$

CREATE OR REPLACE FUNCTION analysis_private.publish_analysis_module(p_module_type text, p_entity_key text, p_module_schema_version text, p_payload_hash text, p_payload jsonb, p_expected_revision bigint, p_expected_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_row analysis_private.analysis_sync_modules; v_next bigint;
begin
  if v_owner is null then raise exception 'ANALYSIS_AUTH_REQUIRED' using errcode='42501'; end if;
  if p_entity_key !~ '^[A-Z0-9][A-Z0-9._-]{0,63}$' or p_payload_hash !~ '^sha256:[0-9a-f]{64}$' or p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'ANALYSIS_ENVELOPE_INVALID';
  end if;
  perform analysis_private.validate_module_payload(p_module_type,p_module_schema_version,p_payload);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text||':'||p_module_type||':'||p_entity_key,0));
  select * into v_row from analysis_private.analysis_sync_modules
    where user_id=v_owner and module_type=p_module_type and entity_key=p_entity_key for update;
  if found and v_row.payload_hash=p_payload_hash then
    return jsonb_build_object('status','no_change','module',analysis_private.module_json(v_row));
  end if;
  if not found then
    if p_expected_revision<>0 or p_expected_hash is not null then return jsonb_build_object('status','conflict'); end if;
    insert into analysis_private.analysis_sync_modules(user_id,module_type,entity_key,module_schema_version,revision,payload_hash,payload)
      values(v_owner,p_module_type,p_entity_key,p_module_schema_version,1,p_payload_hash,p_payload) returning * into v_row;
  else
    if v_row.revision<>p_expected_revision or v_row.payload_hash is distinct from p_expected_hash then return jsonb_build_object('status','conflict'); end if;
    v_next:=v_row.revision+1;
    update analysis_private.analysis_sync_modules set module_schema_version=p_module_schema_version,revision=v_next,payload_hash=p_payload_hash,payload=p_payload,published_at=now()
      where user_id=v_owner and module_type=p_module_type and entity_key=p_entity_key returning * into v_row;
  end if;
  return jsonb_build_object('status','published','module',analysis_private.module_json(v_row));
end $function$

CREATE OR REPLACE FUNCTION analysis_private.validate_module_payload(p_module_type text, p_module_schema_version text, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_keys text[];
begin
  if p_module_type !~ '^[a-z][a-z0-9_]{0,63}$' or p_module_schema_version !~ '^[a-z][a-z0-9-]*\.v[1-9][0-9]*$' or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'ANALYSIS_MODULE_INVALID';
  end if;
  if p_module_type = 'long_term_logic' then
    if p_module_schema_version <> 'long-term-logic.v2' then raise exception 'ANALYSIS_SCHEMA_UNSUPPORTED'; end if;
    select array_agg(key order by key) into v_keys from jsonb_object_keys(p_payload) key;
    if v_keys <> array['confidence','coreDrivers','investmentThesis','keyRisks','logicStatus','nextReviewDate','reviewTriggers'] then
      raise exception 'ANALYSIS_PAYLOAD_INVALID';
    end if;
  else
    raise exception 'ANALYSIS_MODULE_UNSUPPORTED';
  end if;
end $function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION universe_private.list_stock_universe_readers()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception 'UNIVERSE_AUTH_REQUIRED' using errcode='42501'; end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id',id,'label',label,'expiresAt',expires_at) order by created_at),'[]'::jsonb)
    from universe_private.reader_credentials where user_id=v_owner and expires_at>now());
end $function$

CREATE OR REPLACE FUNCTION universe_private.read_stock_universe(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid; v_expiry timestamptz; v_rows jsonb;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
    raise exception 'UNIVERSE_READER_AUTH_REQUIRED' using errcode='42501';
  end if;
  select user_id,expires_at into v_owner,v_expiry from universe_private.reader_credentials
    where token_hash=pg_catalog.sha256(pg_catalog.convert_to(p_token,'UTF8')) and expires_at>now();
  if v_owner is null then raise exception 'UNIVERSE_READER_AUTH_REQUIRED' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('symbol',symbol,'displayName',display_name) order by symbol),'[]'::jsonb)
    into v_rows from public.stock_universe_entries where user_id=v_owner;
  return jsonb_build_object('schemaVersion',1,'userId',v_owner,'credentialExpiresAt',v_expiry,'symbols',v_rows);
end $function$

CREATE OR REPLACE FUNCTION universe_private.register_stock_universe_reader(p_token text, p_label text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid(); v_id uuid; v_expiry timestamptz;
begin
  if v_owner is null then raise exception 'UNIVERSE_AUTH_REQUIRED' using errcode='42501'; end if;
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' or p_label is null or char_length(btrim(p_label)) not between 1 and 40 then
    raise exception 'UNIVERSE_READER_INVALID';
  end if;
  -- Serialize issuance to enforce the small per-owner limit, not Universe ordering.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_owner::text,0));
  if (select count(*) from universe_private.reader_credentials where user_id=v_owner and expires_at>now()) >= 10 then
    raise exception 'UNIVERSE_READER_LIMIT';
  end if;
  insert into universe_private.reader_credentials(user_id,token_hash,label)
    values(v_owner,pg_catalog.sha256(pg_catalog.convert_to(p_token,'UTF8')),btrim(p_label))
    returning id,expires_at into v_id,v_expiry;
  return jsonb_build_object('id',v_id,'userId',v_owner,'expiresAt',v_expiry);
end $function$
